<template><section class="builder-panel outputs-panel"><header class="builder-panel__heading"><strong>◎ &nbsp; Browser Source Output</strong><small>TEST / PREVIEW</small></header><article><div><b>Selected Scene</b><span>Transparent background<br>{{ resolution.width }} × {{ resolution.height }}</span><small>{{ sourceUrl ? `Revision ${revision}` : 'Create a server-side test snapshot' }}</small></div><div class="source-actions"><button v-if="!sourceUrl" :disabled="busy" @click="$emit('create')">Create Test Source</button><template v-else><button :disabled="busy" @click="$emit('update')">Update Test Source</button><button @click="$emit('copy')">Copy URL</button><button @click="$emit('open')">Open</button><button class="danger" :disabled="busy" @click="$emit('revoke')">Revoke</button></template></div></article><p v-if="error" role="alert">{{ error }}</p><p>One URL renders every enabled widget. OBS width: {{ resolution.width }}, height: {{ resolution.height }}. Custom CSS: none.</p></section></template>
<script setup>defineProps({resolution:Object,sourceUrl:String,revision:Number,busy:Boolean,error:String});defineEmits(['create','update','copy','open','revoke','preview'])</script>
